import { create } from 'zustand';
import { useShallow } from 'zustand/react/shallow';

type CartState = {
  items: { id: string; qty: number }[];
  add: (id: string) => void;
  clear: () => void;
};

export const useCart = create<CartState>()((set) => ({
  items: [],
  add: (id) => set((state) => ({ items: [...state.items, { id, qty: 1 }] })),
  clear: () => set({ items: [] }),
}));

// Re-renderiza só quando a quantidade de itens muda
const count = useCart((state) => state.items.length);

// Vários campos: useShallow evita re-render quando nada mudou
const { add, clear } = useCart(useShallow((state) => ({ add: state.add, clear: state.clear })));

import { configureStore, createSlice, type PayloadAction } from '@reduxjs/toolkit';
import { useDispatch, useSelector } from 'react-redux';

const cartSlice = createSlice({
  name: 'cart',
  initialState: { items: [] as string[] },
  reducers: {
    added(state, action: PayloadAction<string>) {
      state.items.push(action.payload); // Immer: parece mutação, gera estado novo
    },
    cleared(state) {
      state.items = [];
    },
  },
});

export const { added, cleared } = cartSlice.actions;

export const store = configureStore({ reducer: { cart: cartSlice.reducer } });
export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;

export const useAppSelector = useSelector.withTypes<RootState>();
export const useAppDispatch = useDispatch.withTypes<AppDispatch>();

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

export function useOrders() {
  return useQuery({
    queryKey: ['orders'],
    queryFn: () => api.get<Order[]>('/orders').then((r) => r.data),
    staleTime: 30_000, // 30 s fresco: não busca de novo ao remontar
  });
}

export function useCreateOrder() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: NewOrder) => api.post<Order>('/orders', input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['orders'] }),
  });
}

