import axios from 'axios';

export const api = axios.create({ baseURL: 'https://api.example.com', timeout: 10_000 });

api.interceptors.request.use((config) => {
  const token = getAccessToken();
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

let refreshing: Promise<string> | null = null;

api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const original = error.config;
    if (error.response?.status !== 401 || original._retry) throw error;
    original._retry = true;
    // Várias requisições com 401 ao mesmo tempo esperam um único refresh
    refreshing ??= refreshToken().finally(() => (refreshing = null));
    original.headers.Authorization = `Bearer ${await refreshing}`;
    return api(original);
  },
);

import { useEffect, useState } from 'react';

export function useDebounce<T>(value: T, delay = 300): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id); // nova digitação cancela o timer anterior
  }, [value, delay]);

  return debounced;
}

// Busca só quando a pessoa para de digitar
const [search, setSearch] = useState('');
const term = useDebounce(search, 400);
const { data } = useQuery({ queryKey: ['products', term], queryFn: () => findProducts(term) });

import { useReducer } from 'react';

type State = { status: 'idle' | 'sending' | 'error'; message?: string };
type Action =
  | { type: 'submit' }
  | { type: 'failed'; message: string }
  | { type: 'reset' };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'submit':
      return { status: 'sending' };
    case 'failed':
      return { status: 'error', message: action.message };
    case 'reset':
      return { status: 'idle' };
  }
}

const [state, dispatch] = useReducer(reducer, { status: 'idle' });
dispatch({ type: 'failed', message: 'Sem conexão' });
